function hammerCrush(a,b,id,w,dmg,crit){const p=b.g.body[id],blunt=['hammer','mace','club'].includes(w.id);if(!blunt||!['ls','rs','lua','rua','lfa','rfa','lh','rh','lt','rt','lsh','rsh','lf','rf'].includes(id)||p.missing||p.fracture?.crushed||dmg<20||p.hp>35||rng()>(crit?.32:.12)*(w.id==='hammer'?1:.7))return false;const held=weapon(b);p.hp=Math.min(p.hp,18);p.fracture={days:60,severe:true,crushed:true};p.pain=Math.max(p.pain,85);p.chronic=Math.max(p.chronic,8);p.grade=M.injuryGrade(p);M.noteInjury(b.g,id,'Trümmerbruch');M.addScar(b.g,id,'Schwerer Trümmerbruch');if(['lt','rt','lsh','rsh','lf','rf'].includes(id))knockdown(b,'Trümmerbruch am Bein',3.6);if(['ls','lua','lfa','lh'].includes(id))dropGear(b,'shield');if(held.hand==='r'?['rs','rua','rfa','rh'].includes(id):['ls','lua','lfa','lh'].includes(id))dropGear(b,held.item?.id===M.gear(b.g,'secondary')?.id?'secondary':'weapon');floater(b.x,b.y-64,'TRÜMMERBRUCH','#edbf88');battleLog(a.g.name+' verursacht mit '+w.name+' einen Trümmerbruch: '+M.partName(id)+' von '+b.g.name+'.');M.sound?.('fall');M.shake=Math.max(M.shake,4);return true;}
